function guideParagraphs(text){return String(text||'').split('\n').filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function guideJump(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function beginnerLesson(id){
 const l=LESSONS[id],g=BEGINNER_GUIDES[id];if(!l||!g)return compactLesson(id);
 state.last=id;save();const next=id<LESSONS.length-1;const sourceUrl=l.sourceUrl||'https://www.runoob.com/python3/'+l.ref;
 const glossary=g.terms.map(t=>`<div class="term-entry"><dt>${esc(t.term)}<span>${esc(t.meaning)}</span></dt><dd>${esc(t.example)}</dd></div>`).join('');
 const symbolRows=g.symbols.map(t=>`<tr><th scope="row">${esc(t.symbol)}</th><td><strong>${esc(t.meaning)}</strong><p>${esc(t.example)}</p></td></tr>`).join('');
 return `<div class="lesson-top"><h1>${esc(l.title)}</h1><button id="font" aria-label="调整讲解字号">字号</button><button id="focus">专注</button><button id="read-mode">切换提纲版</button><button id="favorite">${state.favorites.includes(id)?'已收藏':'收藏'}</button></div>
 <div class="lesson-context"><a href="#module/${l.module}">${esc(l.stage)}</a> · 零基础详解 · 第 ${id+1} / ${LESSONS.length} 节</div>
 <nav class="reading-nav" aria-label="本节阅读位置">${[['g-life','生活例子'],['g-picture','看图理解'],['g-words','认识词语'],['g-worked','一步步算'],['g-formula','公式'],['g-code','逐行代码'],['g-practice','动手练习']].map(([target,label])=>`<button type="button" onclick="guideJump('${target}')">${label}</button>`).join('')}</nav>
 <div class="lesson-layout beginner-layout"><article class="panel prose beginner-prose">
 <section id="g-life" class="teaching-section"><h2>1. 生活中的问题</h2>${guideParagraphs(g.story)}<p>${esc(g.analogy)}</p><div class="learning-goal"><strong>这一课要解决：</strong>${esc(l.problem)}</div></section>
 <section id="g-picture" class="teaching-section"><h2>2. 图解</h2><figure class="lesson-figure"><a href="${esc(g.figure)}" target="_blank" rel="noopener" aria-label="打开本节大图"><img src="${esc(g.figure)}" alt="${esc(g.figureAlt)}" width="760" loading="eager"></a><figcaption>${esc(g.figureCaption)} <a href="${esc(g.figure)}" target="_blank" rel="noopener">查看大图</a></figcaption></figure></section>
 <section id="g-words" class="teaching-section"><h2>3. 基本概念</h2><p>${esc(g.core)}</p><dl class="term-list">${glossary}</dl></section>
 <section id="g-worked" class="teaching-section"><h2>4. 示例与推导</h2>${guideParagraphs(g.explanation)}<div class="worked-example"><h3>拿本页示例亲手算一次</h3>${guideParagraphs(g.worked)}</div><h3>再把直觉接到原理上</h3>${guideParagraphs(l.body)}<p>${esc(g.method)}</p></section>
 <section id="g-formula" class="teaching-section"><h2>5. 公式与记号</h2>${l.formula?`<div class="formula">${esc(l.formula)}</div>${symbolRows?`<div class="symbol-table-wrap"><table class="symbol-table"><thead><tr><th>记号</th><th>怎么读、是什么意思</th></tr></thead><tbody>${symbolRows}</tbody></table></div>`:''}`:'<p>这一课先掌握代码的读法，不需要额外记忆数学公式。</p>'}<details class="syntax-help"><summary>代码符号说明</summary><dl>${g.syntax.map(t=>`<dt>${esc(t.term)}</dt><dd>${esc(t.meaning)}</dd>`).join('')}</dl></details></section>
 <section id="g-code" class="teaching-section"><h2>6. 逐行代码</h2><p>在右侧切换到“教学示例”，再按行号对照。缩进和括号也是代码的一部分。</p><ol class="code-explanations">${g.lines.map(r=>`<li><div class="code-line-label">第 ${r.line} 行 · ${esc(r.title)}</div><pre><code>${esc(r.code)}</code></pre><p>${esc(r.explain)}</p>${r.substeps?.length?`<div class="substep-heading">把这一行里面的操作再拆开：</div><ol class="code-substeps">${r.substeps.map(step=>`<li><code>${esc(step.code)}</code><p>${esc(step.explain)}</p></li>`).join('')}</ol>`:''}</li>`).join('')}</ol></section>
 <section id="g-trace" class="teaching-section"><h2>7. 运行过程</h2><p>以下为教学示例的预录执行过程；修改代码后的结果请点击“运行代码”。</p>${g.observation.events.length?`<div class="trace-viewer"><div class="trace-toolbar"><button id="trace-prev" type="button">上一步</button><span id="trace-position" aria-live="polite"></span><button id="trace-next" type="button">下一步</button></div><div id="trace-detail" aria-live="polite"></div></div>${g.observation.omitted?`<p class="reading-tip">这段示例共记录 ${g.observation.total} 个值变化点，长循环中间省略了 ${g.observation.omitted} 个，只展示开始与末尾的代表点。</p>`:''}`:'<p>这段代码没有需要单独记录的顶层变量变化，可以直接对照逐行解释和输出。</p>'}<details class="answer-details"><summary>查看示例输出</summary><pre>${esc(g.observation.output||'本例不产生文字输出。')}</pre></details></section>
 <section id="g-practice" class="teaching-section"><h2>8. 动手练习</h2><div class="guided-experiment">${guideParagraphs(g.experiment)}</div><h3>理解自测</h3><p>${esc(g.check)}</p><details class="answer-details"><summary>查看解释</summary><p>${esc(g.checkAnswer)}</p></details><div class="toolbar"><button class="primary" onclick="go('exercise/${relatedExercise(id)}')">做本节编程练习</button><button id="done">${state.done.includes(id)?'✓ 已学完':'标记本节已学完'}</button></div><label>目前掌握情况 <select id="mastery" class="select-state">${['尚未学习','初步接触','需要巩固','基本掌握'].map(s=>`<option ${mastery(id)===s?'selected':''}>${s}</option>`).join('')}</select></label></section>
 <section class="teaching-section"><h2>9. 总结与易错点</h2><div class="callout">${esc(l.error)}</div><p>${esc(l.explain)}</p><h3>笔记</h3><textarea class="note" id="note" placeholder="我理解的是……我还不确定的是……">${esc(state.notes[id]||'')}</textarea><span id="note-status" class="saved">自动保存在此浏览器</span><div class="row lesson-bottom-nav"><a href="#${id?'lesson/'+(id-1):'route'}">← ${id?'上一节':'课程目录'}</a><a href="#${next?'lesson/'+(id+1):'projects'}">${next?'下一节':'项目实践'} →</a></div><a class="source" href="${esc(sourceUrl)}" target="_blank" rel="noopener">参考：${esc(l.sourceTitle||'菜鸟教程')} ↗</a></section>
 </article><aside class="lesson-lab" aria-label="配套代码实验">${lessonWorkspace(id)}${l.framework?`<section class="framework-example"><h3>进一步：本地框架写法</h3><p>先看懂上面的原理实验，再读这个版本。需本机安装对应依赖；这段框架代码不在浏览器执行，尚未安装依赖验证。</p><button id="download-framework">下载 .py 文件</button><pre class="hint">${esc(l.framework)}</pre><a href="#resources">查看环境与资料 →</a></section>`:''}</aside></div>`;
}
function bindBeginner(id){
 const toggle=document.getElementById('read-mode');if(toggle)toggle.onclick=()=>{state.outlineMode=!state.outlineMode;save();render()};
 const g=BEGINNER_GUIDES[id];if(!g||!document.getElementById('trace-detail'))return;
 let index=0;
 function paint(){const event=g.observation.events[index];if(!event)return;document.getElementById('trace-position').textContent=`检查点 ${index+1} / ${g.observation.events.length}`;document.getElementById('trace-detail').innerHTML=`<h3>执行第 ${event.line} 行之后</h3><pre><code>${esc(LESSONS[id].code.split('\n')[event.line-1]||'')}</code></pre><p>此时有变化的值：</p><dl class="trace-values">${Object.entries(event.values).map(([name,value])=>`<dt>${esc(name)}</dt><dd><code>${esc(value)}</code></dd>`).join('')}</dl>`;document.getElementById('trace-prev').disabled=index===0;document.getElementById('trace-next').disabled=index===g.observation.events.length-1;}
 document.getElementById('trace-prev').onclick=()=>{index=Math.max(0,index-1);paint()};document.getElementById('trace-next').onclick=()=>{index=Math.min(g.observation.events.length-1,index+1);paint()};paint();
}
